class TestPatchOutcomes:
    def test_complete_json_reports_effective_budget_and_no_omissions(self, repo, capsys):
        code, output = run(repo, "diff", "HEAD^", "HEAD", "--patch", "--json",
                           "--filter", "Store::get", "--budget", "10000")
        payload = json.loads(output)
        assert code == 0
        assert payload["status"] == "complete"
        assert payload["omitted"] == [] and payload["omitted_count"] == 0
        assert not payload["truncated"]
        assert payload["tokens"] <= payload["budget"] < payload["requested_budget"] == 10000
        assert "self.data[key]" in payload["patch"]
        assert capsys.readouterr().err == ""

    def test_nothing_fits_json_is_not_a_successful_empty_patch(self, repo, capsys):
        code, output = run(repo, "diff", "HEAD^", "HEAD", "--patch", "--json", "--budget", "0")
        payload = json.loads(output)
        assert code == 6
        assert payload["status"] == "nothing_fits"
        assert payload["error"] == "budget too small"
        assert payload["patch"] == "" and payload["tokens"] == 0
        assert payload["budget"] == payload["requested_budget"] == 0
        assert payload["truncated"]
        assert set(payload["omitted"]) == {c["id"] for c in payload["changes"]}
        assert payload["omitted_count"] == len(payload["omitted"]) > 0
        assert capsys.readouterr().err == ""

    def test_nothing_fits_text_uses_stderr_without_false_no_changes(self, repo, capsys):
        code, output = run(repo, "diff", "HEAD^", "HEAD", "--patch", "--budget", "0")
        diagnostic = capsys.readouterr().err
        assert code == 6 and output == ""
        assert "nothing fits" in diagnostic
        assert "omitted" in diagnostic and "effective budget 0" in diagnostic
        assert "no material changes" not in diagnostic

    def test_partial_patch_preserves_code_and_exposes_omissions(self, repo, capsys):
        args = ("diff", "HEAD^", "HEAD", "--patch", "--budget", "100")
        code, output = run(repo, *args, "--json")
        payload = json.loads(output)
        assert code == 0 and payload["status"] == "partial"
        assert payload["truncated"] and payload["omitted_count"] > 0
        assert payload["tokens"] <= payload["budget"] == 100
        assert "@@" in payload["patch"]
        assert capsys.readouterr().err == ""
        code, output = run(repo, *args)
        assert code == 0 and output.rstrip() == payload["patch"].rstrip()
        diagnostic = capsys.readouterr().err
        assert "partial patch" in diagnostic
        assert f'{payload["omitted_count"]} entities omitted' in diagnostic
        assert "effective budget 100" in diagnostic

    def test_raw_cap_is_explained_when_requested_budget_cannot_help(self, repo, monkeypatch, capsys):
        monkeypatch.setattr(type(repo), "raw_diff", lambda *args: "tiny")
        code, output = run(repo, "diff", "HEAD^", "HEAD", "--patch", "--budget", "10000")
        assert code == 6 and output == ""
        diagnostic = capsys.readouterr().err
        assert "effective budget 1" in diagnostic
        assert "requested 10000" in diagnostic and "raw-diff cap" in diagnostic

    def test_clean_tree_is_complete_not_nothing_fits(self, repo):
        code, output = run(repo, "diff", "--patch", "--json", "--budget", "0")
        payload = json.loads(output)
        assert code == 0 and payload["status"] == "complete"
        assert payload["changes"] == [] and payload["omitted"] == []

    def test_material_move_without_hunks_is_not_no_changes(self, repo, capsys):
        repo._run("mv", "app.py", "renamed.py")
        code, output = run(repo, "diff", "--patch")
        assert code == 0
        assert "material changes; no textual hunks" in output
        assert "no material changes" not in output
        assert capsys.readouterr().err == ""
        payload = json.loads(run(repo, "diff", "--patch", "--json")[1])
        assert payload["status"] == "complete" and payload["changes"]
        assert payload["patch"] == "" and payload["omitted"] == []


