class TestHistoryTakesRevisionsLikeEveryOtherCommand:
    """`gita diff <base> <head>` works, so `gita history <name> <base> <head>` must.

    Requiring --since here cost two turns in every repetition of `gin-history`:
    the agent tried the positional form, was rejected, ran `gita history --help`,
    and retried. An inconsistent surface is a surface that has to be read.
    """

    def test_positional_revisions_are_accepted(self, repo):
        code, output = run(repo, "history", "handle", "HEAD^", "HEAD")
        assert code == 0
        assert "handle" in output

    def test_a_single_positional_revision_means_since(self, repo):
        positional = run(repo, "history", "handle", "HEAD^")
        flagged = run(repo, "history", "handle", "--since", "HEAD^")
        assert positional == flagged

    def test_the_flag_form_still_works(self, repo):
        code, _ = run(repo, "history", "handle", "--since", "HEAD^", "--until", "HEAD")
        assert code == 0

    def test_flags_win_over_positionals(self, repo):
        explicit = run(repo, "history", "handle", "HEAD~1", "--since", "HEAD^")
        assert explicit[0] == 0

    @pytest.mark.parametrize("command", ["history", "katha"])
    def test_two_commits_select_repository_history(self, repo, command):
        positional = run(repo, command, "HEAD^", "HEAD", "--json")
        flagged = run(repo, "history", "--since", "HEAD^", "--until", "HEAD", "--json")
        assert positional == flagged

    def test_one_token_remains_an_entity_even_when_a_ref_matches(self, repo):
        repo._run("branch", "handle")
        code, output = run(repo, "history", "handle", "--json")
        assert code == 0
        assert json.loads(output)["entity"] == "handle"


class TestSpeaksGitsDialect:
    """Agents transfer git habits, and a rejected guess costs a whole turn.

    Across 1,209 recorded invocations they typed flags gita did not have:
    `--base`/`--head` (12), `--no-pager` (9), `--stat` (4), `--oneline` (3).
    Where git's spelling means the same thing here, accept it.
    """

    def test_base_and_head_may_be_flags(self, repo):
        positional = run(repo, "diff", "HEAD^", "HEAD")
        flagged = run(repo, "diff", "--base", "HEAD^", "--head", "HEAD")
        assert flagged == positional

    def test_no_pager_is_accepted_and_ignored(self, repo):
        assert run(repo, "--no-pager", "diff", "HEAD^", "HEAD") == \
               run(repo, "diff", "HEAD^", "HEAD")

    def test_stat_means_summary_only(self, repo):
        assert run(repo, "diff", "HEAD^", "HEAD", "--stat") == \
               run(repo, "diff", "HEAD^", "HEAD", "--brief")

    def test_oneline_means_summary_only(self, repo):
        assert run(repo, "diff", "HEAD^", "HEAD", "--oneline") == \
               run(repo, "diff", "HEAD^", "HEAD", "--brief")

    def test_history_accepts_them_too(self, repo):
        code, _ = run(repo, "history", "handle", "--oneline")
        assert code == 0


