ENVELOPE_KEYS = {
    "schema_version", "command", "status", "scope", "generation", "revision",
    "boundary", "policy", "refs", "freshness", "coverage", "results", "page",
    "omitted", "error",
}


def _indexed_json(repo, *args, expected=0, budget=20000, error=None):
    from gita.context import count_tokens

    code, output = run(repo, *args, "--json", "--budget", str(budget))
    assert code == expected, output
    assert count_tokens(output) <= budget
    return _assert_indexed_envelope(json.loads(output), error=error)


def _assert_indexed_envelope(payload, *, error=None):
    import re

    assert set(payload) >= ENVELOPE_KEYS
    assert isinstance(payload["results"], list)
    assert isinstance(payload["command"], str) and payload["command"]
    assert isinstance(payload["status"], str) and payload["status"]
    assert payload["schema_version"] is not None
    generation = payload["generation"]
    assert generation is None or (
        isinstance(generation, str) and re.fullmatch(r"gen1_[0-9a-f]{32}", generation)
    )
    if error is None:
        assert payload["error"] is None
    else:
        failure = payload["error"]
        assert set(failure) >= {"code", "message", "retryable", "recovery"}
        if isinstance(error, str):
            assert failure["code"] == error
        elif error is not True:
            assert failure["code"] in error
        assert isinstance(failure["code"], str) and failure["code"]
        assert isinstance(failure["message"], str) and failure["message"]
        assert type(failure["retryable"]) is bool
        assert failure["recovery"]
    return payload


def _indexed_oid(value, commit=None):
    import re

    assert set(value) >= {"object_format", "hex"}
    assert value["object_format"] in {"sha1", "sha256"}
    width = 40 if value["object_format"] == "sha1" else 64
    assert re.fullmatch(rf"[0-9a-f]{{{width}}}", value["hex"])
    if commit is not None:
        assert value["hex"] == commit


def _indexed_page(payload, *, total):
    page, omitted = payload["page"], payload["omitted"]
    assert set(page) >= {"shown", "total", "next_cursor"}
    assert set(omitted) >= {"count", "count_known"}
    assert page["shown"] == len(payload["results"])
    assert page["total"] == total
    assert omitted["count_known"] is True
    assert omitted["count"] == total - page["shown"]
    cursor = page["next_cursor"]
    assert cursor is None or (isinstance(cursor, str) and 0 < len(cursor.encode("ascii")) <= 4096)


def _forbid_index_work(*args, **kwargs):
    pytest.fail("An indexed read attempted to write, parse, build, or fall back to legacy history")


