class TestIndexedHistoryPatches:
    def test_default_history_includes_before_and_after_code(self, indexed5):
        payload = _indexed_json(indexed5["repo"], "history", indexed5["eid"], "--indexed")
        event = payload["results"][0]
        assert event["patch_status"] == "included"
        assert "@@" in event["patch"]
        assert "-" + indexed5["sources"][-2].decode().splitlines()[-1] in event["patch"]
        assert "+" + indexed5["sources"][-1].decode().splitlines()[-1] in event["patch"]

    def test_brief_history_does_not_read_source(self, indexed5, monkeypatch):
        from gita.index.query import IndexSession

        monkeypatch.setattr(IndexSession, "source", _forbid_index_work)
        payload = _indexed_json(indexed5["repo"], "history", indexed5["eid"], "--indexed", "--brief")
        assert len(payload["results"]) == 5
        assert all("patch" not in event and "patch_status" not in event for event in payload["results"])

    def test_add_rename_and_move_preserve_the_actual_source_transition(self, indexed5):
        payload = _indexed_json(indexed5["repo"], "history", indexed5["eid"], "--indexed", "--order", "oldest")
        added, edited, renamed, moved, edited_again = payload["results"]
        assert added["patch"].startswith("--- /dev/null\n+++ b/auth.py::validate_token\n")
        assert "-def validate_token(raw):" in renamed["patch"]
        assert "+def check_token(raw):" in renamed["patch"]
        assert moved["patch_status"] == "unchanged" and "patch" not in moved
        assert moved["source"]["path"] == "auth.py"
        assert moved["destination"]["path"] == "security.py"
        assert edited["patch_status"] == edited_again["patch_status"] == "included"

    def test_observed_boundary_is_not_rendered_as_an_addition(self, refactor_repo, monkeypatch):
        from gita.index.query import IndexSession

        repo = refactor_repo["repo"]
        _indexed_json(repo, "index", "--since", "HEAD")
        monkeypatch.setattr(IndexSession, "source", _forbid_index_work)
        payload = _indexed_json(repo, "history", "check_token", "--indexed")
        assert payload["results"][0]["flags"] == ["observed"]
        assert payload["results"][0]["patch_status"] == "not_applicable"
        assert "patch" not in payload["results"][0]

    def test_removal_shows_committed_source_not_worktree_text(self, refactor_repo):
        repo = refactor_repo["repo"]
        _indexed_json(repo, "index")
        eid = _indexed_json(repo, "id", "check_token")["results"][0]["eid"]
        (repo.root / "security.py").write_bytes(b"# removed\n")
        repo._run("add", "security.py")
        repo._run("commit", "-qm", "remove validator")
        _indexed_json(repo, "index")
        (repo.root / "security.py").write_bytes(b"uncommitted text must never be used\n")
        event = _indexed_json(repo, "history", eid, "--indexed", "--limit", "1")["results"][0]
        assert "+++ /dev/null\n" in event["patch"]
        assert "-def check_token(raw):" in event["patch"]
        assert "uncommitted" not in event["patch"]

    def test_patch_hunks_use_absolute_file_lines(self, repo):
        _indexed_json(repo, "index")
        event = _indexed_json(repo, "history", "handle", "--indexed", "--limit", "1")["results"][0]
        old_line = event["source"]["span"]["start_line"]
        new_line = event["destination"]["span"]["start_line"]
        assert old_line > 1 and new_line > 1
        assert f"@@ -{old_line},3 +{new_line},3 @@" in event["patch"]
        assert "\\ No newline at end of file\n" in event["patch"]

    @pytest.mark.parametrize("as_json", [False, True])
    def test_patch_budget_preserves_metadata_and_marks_omitted_patches(self, indexed5, as_json):
        from gita.cli.indexed import _serialized
        from gita.context import count_tokens

        repo = indexed5["repo"]
        brief = _indexed_json(repo, "history", indexed5["eid"], "--indexed", "--brief")
        for event in brief["results"]:
            event["patch_status"] = "omitted_budget"
        budget = count_tokens(_serialized(brief, as_json))
        options = ("--json",) if as_json else ()
        code, output = run(repo, "history", indexed5["eid"], "--indexed", "--budget", str(budget), *options)
        assert code == 0, output
        assert count_tokens(output) <= budget
        if as_json:
            payload = json.loads(output)
            assert payload["page"]["shown"] == 5
            missing = [event for event in payload["results"] if event["patch_status"] == "omitted_budget"]
            assert missing
            assert all("patch" not in event and event["destination"] is not None for event in missing)
        else:
            assert "shown 5 total 5 omitted 0" in output
            assert "patch omitted: budget" in output
            assert "gita_source" in output

