class TestIndexedRangeHistory:
    def test_range_returns_all_events_and_pages_without_duplicates(self, indexed5):
        repo = indexed5["repo"]
        base, head = indexed5["commits"][0], indexed5["commits"][-1]
        complete = _indexed_json(repo, "history", base, head, "--indexed")
        assert complete["results"]
        assert all(event["commit"]["hex"] != base for event in complete["results"])
        cursor = None
        events = []
        while True:
            options = ("--cursor", cursor) if cursor else ()
            page = _indexed_json(repo, "history", base, head, "--indexed", "--limit", "1", *options)
            events.extend(page["results"])
            cursor = page["page"]["next_cursor"]
            if cursor is None:
                break
        assert events == complete["results"]
        assert len({event["id"] for event in events}) == len(events)

    def test_range_flags_and_alias_match_positionals(self, indexed5):
        repo = indexed5["repo"]
        positional = _indexed_json(repo, "history", "HEAD~4", "HEAD", "--indexed")
        flagged = _indexed_json(repo, "katha", "--since", "HEAD~4", "--until", "HEAD", "--indexed")
        assert positional == flagged

    def test_range_cursor_rejects_different_endpoints(self, indexed5):
        repo = indexed5["repo"]
        first = _indexed_json(repo, "history", "HEAD~4", "HEAD", "--indexed", "--limit", "1")
        _indexed_json(repo, "history", "HEAD~3", "HEAD", "--indexed", "--cursor",
                      first["page"]["next_cursor"], expected=2, error="invalid_cursor")

    def test_range_rejects_reverse_order(self, indexed5):
        _indexed_json(indexed5["repo"], "history", "HEAD", "HEAD~4", "--indexed",
                      expected=2, error="outside_scope")

    def test_equal_endpoints_are_an_empty_success(self, indexed5):
        payload = _indexed_json(indexed5["repo"], "history", "HEAD", "HEAD", "--indexed")
        assert payload["results"] == []
        assert payload["page"]["total"] == 0

    def test_range_cursor_keeps_its_generation_after_index_update(self, refactor_repo):
        repo = refactor_repo["repo"]
        _indexed_json(repo, "index")
        base, head = refactor_repo["commits"][0], refactor_repo["commits"][-1]
        first = _indexed_json(repo, "history", base, head, "--indexed", "--limit", "1")
        repo._run("commit", "--allow-empty", "-qm", "advance tip")
        updated = _indexed_json(repo, "index")
        following = _indexed_json(repo, "history", base, head, "--indexed", "--limit", "1",
                                  "--cursor", first["page"]["next_cursor"])
        assert updated["generation"] != first["generation"]
        assert following["generation"] == first["generation"]
        assert following["results"][0]["id"] != first["results"][0]["id"]

    def test_range_cannot_consume_an_entity_history_cursor(self, indexed5):
        repo = indexed5["repo"]
        first = _indexed_json(repo, "history", indexed5["eid"], "--indexed", "--limit", "1")
        _indexed_json(repo, "history", "HEAD~4", "HEAD", "--indexed", "--cursor",
                      first["page"]["next_cursor"], expected=2, error="invalid_cursor")


