    def test_build_envelope_uses_persisted_scope_generation_and_provenance(self, indexed5):
        import re
        from gita.index.store import IndexStore

        payload = indexed5["built"]
        assert payload["command"] == "index"
        assert payload["status"] == "ready"
        generation = payload["generation"]
        assert isinstance(generation, str) and re.fullmatch(r"gen1_[0-9a-f]{32}", generation)
        with IndexStore.open(IndexStore.locate(indexed5["repo"]), read_only=True) as store:
            record = store.generation(generation)
            context = store._context(record["context_id"])
            scope_id = store.connection.execute("SELECT id FROM scope WHERE name = ?", ("default",)).fetchone()[0]
            assert store.published_generation("default") == generation
        assert set(payload["scope"]) >= {"name", "id", "first_parent"}
