        assert payload["boundary"]["parents"] == []
        assert set(payload["policy"]) >= {"parse_fingerprint", "match_fingerprint", "context"}
        assert payload["policy"]["parse_fingerprint"] == context.parse_fingerprint.hex()
        assert payload["policy"]["match_fingerprint"] == context.match_fingerprint.hex()
