    @pytest.mark.parametrize("repository_position", ["before", "after"])
    def test_new_flags_accept_repository_selection_on_either_side(self, refactor_repo, repository_position):
        from gita.context import count_tokens

        repo = refactor_repo["repo"]

        def invoke(*args, expected=0, error=None):
            arguments = [*args, "--json", "--budget", "20000"]
            if repository_position == "before":
                code, output = run(repo, *arguments)
            else:
                out = io.StringIO()
                code = main([*arguments, "-C", str(repo.root)], out=out)
                output = out.getvalue()
            assert code == expected, output
            assert count_tokens(output) <= 20000
            return _assert_indexed_envelope(json.loads(output), error=error)

        built = invoke("index", "--scope", "audit", "--ref", "HEAD",
                       "--since", refactor_repo["commits"][0], "--rebuild")
        generation = built["generation"]
        assert built["scope"]["name"] == "audit"
        assert built["boundary"]["kind"] == "bounded"
        selected = invoke("id", "validate_token", "--scope", "audit", "--at", "HEAD",
                          "--historical", "--generation", generation, "--limit", "1")
        eid = selected["results"][0]["eid"]
        page = invoke("history", eid, "--indexed", "--scope", "audit", "--at", "HEAD",
                      "--generation", generation, "--order", "oldest", "--limit", "1")
        cursor = page["page"]["next_cursor"]
        assert cursor
        following = invoke("history", eid, "--indexed", "--scope", "audit", "--cursor", cursor,
                           "--generation", generation, "--order", "oldest", "--limit", "1")
        _indexed_oid(following["results"][0]["commit"], refactor_repo["commits"][1])
        invoke("id", eid, "--scope", "audit", "--cursor", "not-a-cursor", expected=2, error="invalid_cursor")
        status = invoke("index", "--status", "--scope", "audit")
        assert status["generation"] == generation
        unavailable = invoke("index", "--verify", "--scope", "audit", "--generation", generation,
                             "--source-check", expected=3, error="verification_unavailable")
        assert unavailable["status"] == "unverified"
        rebuilt = invoke("index", "--scope", "audit", "--rebuild")
        assert rebuilt["generation"] != generation
        invoke("index", "--gc", "--scope", "audit", "--generation", generation)

