    def test_history_defaults_to_twenty_newest_and_alias_preserves_five_events(self, indexed5, monkeypatch, capsys):
        from gita.cli import DEFAULT_BUDGET
        from gita.context import count_tokens
        from gita.index import query

        history = query.IndexSession.history
        calls = []

        def recording(session, eid, **options):
            calls.append(options)
            return history(session, eid, **options)

        monkeypatch.setattr(query.IndexSession, "history", recording)
        code, output = run(indexed5["repo"], "history", indexed5["eid"], "--indexed", "--json")
        assert code == 0, output
        assert count_tokens(output) <= DEFAULT_BUDGET
        payload = _assert_indexed_envelope(json.loads(output))
        assert payload["command"] == "history"
        assert calls and calls[-1]["limit"] == 20
        assert calls[-1].get("order", "newest") == "newest"
        _indexed_page(payload, total=5)
        assert len(payload["results"]) == 5
        assert payload["page"]["next_cursor"] is None
        for sequence, event in zip(reversed(range(5)), payload["results"], strict=True):
            assert set(event) >= {"eid", "material", "flags", "commit", "parent", "source", "destination"}
            assert event["eid"] == indexed5["eid"] and event["material"] is True
            assert isinstance(event["flags"], list) and event["flags"]
            _indexed_oid(event["commit"], indexed5["commits"][sequence])
            if sequence == 0:
                assert event["parent"] is None and event["source"] is None
            else:
                _indexed_oid(event["parent"], indexed5["commits"][sequence - 1])
            destination = event["destination"]
            assert set(destination) >= {"id", "commit", "path_bytes_b64", "names", "span"}
            _indexed_oid(destination["commit"], indexed5["commits"][sequence])
            assert destination["names"] == [indexed5["names"][sequence]]
            assert destination["span"] == {
                "start_byte": 0, "end_byte": len(indexed5["sources"][sequence]) - 1,
                "start_line": 1, "end_line": indexed5["sources"][sequence].count(b"\n"),
            }
        alias = _indexed_json(indexed5["repo"], "katha", indexed5["eid"], "--indexed")
        for field in ("command", "status", "generation", "results", "page", "omitted"):
            assert alias[field] == payload[field]
        limited = _indexed_json(indexed5["repo"], "history", indexed5["eid"], "--indexed", "--limit", "1")
        _indexed_page(limited, total=5)
        assert len(limited["results"]) == 1 and limited["page"]["next_cursor"]
        assert capsys.readouterr().err == ""

