    def test_cursor_recovers_old_generation_and_revision_before_open_after_extension(self, refactor_repo):
        repo, commits = refactor_repo["repo"], refactor_repo["commits"]
        old = _indexed_json(repo, "index", "--ref", commits[2])
        eid = _indexed_json(repo, "id", "check_token")["results"][0]["eid"]
        first = _indexed_json(repo, "history", eid, "--indexed", "--limit", "1")
        _indexed_page(first, total=3)
        cursor = first["page"]["next_cursor"]
        assert cursor
        current = _indexed_json(repo, "index")
        assert current["generation"] != old["generation"]
        _indexed_json(repo, "index", "--scope", "other")
        for override in (("--generation", current["generation"]), ("--at", commits[-1]),
                         ("--order", "oldest"), ("--scope", "other")):
            _indexed_json(repo, "history", eid, "--indexed", "--cursor", cursor, *override,
                          expected=2, error="invalid_cursor")
        events, seen = list(first["results"]), {cursor}
        for page_number in range(2):
            page = _indexed_json(repo, "history", eid, "--indexed", "--cursor", cursor, "--limit", "1")
            assert page["generation"] == old["generation"]
            _indexed_oid(page["revision"]["pinned"], commits[2])
            _indexed_page(page, total=3)
            assert len(page["results"]) == 1
            events.extend(page["results"])
            cursor = page["page"]["next_cursor"]
            if page_number == 0:
                assert cursor and cursor not in seen
                seen.add(cursor)
            else:
                assert cursor is None
        assert [event["commit"]["hex"] for event in events] == list(reversed(commits[:3]))
        assert len({event["id"] for event in events}) == 3
        explicit = _indexed_json(repo, "history", eid, "--indexed", "--generation", old["generation"])
        assert explicit["results"] == events

    def test_invalid_and_wrong_action_cursors_are_usage_errors(self, indexed5):
        repo, eid = indexed5["repo"], indexed5["eid"]
        history = _indexed_json(repo, "history", eid, "--indexed", "--limit", "1")
        for command in (("id", eid), ("history", eid, "--indexed")):
            for cursor in ("", "not-a-cursor", "x" * 4097):
                _indexed_json(repo, *command, "--cursor", cursor, expected=2, error="invalid_cursor")
        _indexed_json(repo, "id", eid, "--cursor", history["page"]["next_cursor"],
                      expected=2, error="invalid_cursor")

    def test_gc_is_explicit_scope_checked_and_invalidates_only_collected_cursors(self, refactor_repo):
        from gita.index.store import IndexStore

        repo = refactor_repo["repo"]
        old = _indexed_json(repo, "index", "--ref", refactor_repo["commits"][2])
        eid = _indexed_json(repo, "id", "check_token")["results"][0]["eid"]
        page = _indexed_json(repo, "history", eid, "--indexed", "--limit", "1")
        current = _indexed_json(repo, "index", "--rebuild")
        other = _indexed_json(repo, "index", "--scope", "other")
        with IndexStore.open(IndexStore.locate(repo), read_only=True) as store:
            assert store.generation(current["generation"])["predecessor"] is None
        _indexed_json(repo, "index", "--gc", "--generation", current["generation"],
                      expected=4, error="generation_in_use")
        _indexed_json(repo, "index", "--gc", "--generation", old["generation"], "--scope", "other",
                      expected=2, error="outside_scope")
        retained = _indexed_json(repo, "history", eid, "--indexed", "--cursor", page["page"]["next_cursor"])
        assert retained["generation"] == old["generation"]
        _indexed_json(repo, "index", "--gc", "--generation", old["generation"])
        _indexed_json(repo, "history", eid, "--indexed", "--cursor", page["page"]["next_cursor"],
                      expected=3, error="generation_gone")
        _indexed_json(repo, "id", eid, "--generation", old["generation"], expected=3, error="generation_gone")
        assert _indexed_json(repo, "index", "--status")["generation"] == current["generation"]
        assert _indexed_json(repo, "index", "--status", "--scope", "other")["generation"] == other["generation"]

    def test_id_owns_one_readonly_snapshot_and_never_writes_or_falls_back(self, indexed5, monkeypatch):
        import sqlite3
        import gita.history as legacy_history
        from gita.index import builder, query
        from gita.index.store import IndexStore

        opened = []
        open_store = IndexStore.open.__func__
        resolve = query.IndexSession.resolve

        def recording(cls, *args, **kwargs):
            store = open_store(cls, *args, **kwargs)
            opened.append(store)
            return store

        def checked_resolve(session, *args, **kwargs):
            assert len(opened) == 1
            assert opened[0].read_only is True
            assert opened[0].connection.in_transaction
            return resolve(session, *args, **kwargs)

        monkeypatch.setattr(IndexStore, "open", classmethod(recording))
        monkeypatch.setattr(IndexStore, "create", _forbid_index_work)
        monkeypatch.setattr(IndexStore, "transaction", _forbid_index_work)
        monkeypatch.setattr(query.IndexSession, "resolve", checked_resolve)
        monkeypatch.setattr(builder, "build", _forbid_index_work)
        monkeypatch.setattr(builder, "EvidenceWorker", _forbid_index_work)
        monkeypatch.setattr(legacy_history, "entity_history", _forbid_index_work)
        result = _indexed_json(indexed5["repo"], "id", indexed5["eid"])
        assert result["results"][0]["eid"] == indexed5["eid"]
        assert len(opened) == 1
        with pytest.raises(sqlite3.ProgrammingError):
            opened[0].connection.execute("SELECT 1")

    @pytest.mark.parametrize("policy", ["parse", "match"])
    def test_interpretation_mismatch_is_exit_three_with_recovery_and_no_fallback(self, indexed5, monkeypatch, policy):
        import gita.history as legacy_history
        from gita.index import builder, evidence, matching
        from gita.index.store import IndexStore

        module = evidence if policy == "parse" else matching
        name = f"{policy}_fingerprint"
        original = getattr(module, name)

        def changed(*args, **kwargs):
            fingerprint = original(*args, **kwargs)
            return bytes([fingerprint[0] ^ 1]) + fingerprint[1:]

        path = IndexStore.locate(indexed5["repo"])
        before = path.read_bytes()
        monkeypatch.setattr(module, name, changed)
        monkeypatch.setattr(builder, "build", _forbid_index_work)
        monkeypatch.setattr(legacy_history, "entity_history", _forbid_index_work)
        for command in (("id", indexed5["eid"]), ("history", indexed5["eid"], "--indexed")):
            payload = _indexed_json(indexed5["repo"], *command, expected=3, error=f"{policy}_mismatch")
            assert payload["results"] == []
        assert path.read_bytes() == before

    def test_corrupt_database_is_exit_five_and_is_preserved_even_for_status(self, repo, monkeypatch):
        from gita.index.store import IndexStore

        path = IndexStore.locate(repo)
        path.parent.mkdir(parents=True)
        damaged = b"This is not a SQLite database.\x00\xff\x80"
        path.write_bytes(damaged)
        monkeypatch.setattr(IndexStore, "create", _forbid_index_work)
        for command in (("index", "--status"), ("index",), ("id", "handle"), ("history", "handle", "--indexed")):
            payload = _indexed_json(repo, *command, expected=5, error="corrupt")
            assert payload["status"] != "not_built"
            assert payload["results"] == []
            assert path.read_bytes() == damaged

    @pytest.mark.parametrize("failure_family", ["build", "store"])
    def test_typed_build_and_store_failures_keep_the_new_exit_mapping(self, repo, monkeypatch, capsys, failure_family):
        from gita.index import builder
        from gita.index.store import IndexStoreError

        cases = ((builder.BuildError, "busy", 4), (builder.BuildError, "resource_limit", 4)) \
            if failure_family == "build" else ((IndexStoreError, "corrupt", 5),)
        for error_type, error_code, expected in cases:
            failure = error_type(error_code, "Injected CLI boundary failure")

            def rejected(*args, **kwargs):
                raise failure

            monkeypatch.setattr(builder, "build", rejected)
            payload = _indexed_json(repo, "index", expected=expected, error=error_code)
            assert payload["results"] == []
            if error_code == "busy":
                assert payload["error"]["retryable"] is True
            elif error_code == "corrupt":
                assert payload["error"]["retryable"] is False
            assert "Traceback" not in capsys.readouterr().err

    def test_default_text_is_concise_and_contains_identity_and_history_locations(self, refactor_repo, capsys):
        from gita.context import count_tokens

        repo = refactor_repo["repo"]
        for command in (("index",), ("id", "check_token"), ("history", "check_token", "--indexed")):
            code, output = run(repo, *command, "--budget", "2000")
            assert code == 0, output
            assert output.strip() and not output.lstrip().startswith(("{", "["))
            assert count_tokens(output) <= 2000
            if command[0] == "index":
                assert "ready" in output.lower()
            else:
                assert "eid1_" in output
                assert "check_token" in output and "security.py" in output
            assert capsys.readouterr().err == ""

