    def test_scope_tip_is_not_head_or_dirty_state_and_status_does_not_repin(self, refactor_repo):
        from gita.index.store import IndexStore

        repo, commits = refactor_repo["repo"], refactor_repo["commits"]
        built = _indexed_json(repo, "index", "--scope", "prefix", "--ref", commits[2])
        path = IndexStore.locate(repo)
        before = path.read_bytes()
        staged = b"def staged_only():\n    return 1\n"
        dirty = b"def worktree_only():\n    return 2\n"
        (repo.root / "security.py").write_bytes(staged)
        repo._run("add", "security.py")
        (repo.root / "security.py").write_bytes(dirty)
        status = _indexed_json(repo, "index", "--status", "--scope", "prefix")
        assert status["generation"] == built["generation"]
        _indexed_oid(status["revision"]["pinned"], commits[2])
        assert status["freshness"]["status"] in {"behind", "unchecked"}
        selected = _indexed_json(repo, "id", "check_token", "--scope", "prefix")
        occurrence = selected["results"][0]["occurrence"]
        _indexed_oid(occurrence["commit"], commits[2])
        assert occurrence["path"] == "auth.py"
        history = _indexed_json(repo, "history", "check_token", "--indexed", "--scope", "prefix")
        _indexed_page(history, total=3)
        for token in ("worktree_only", "staged_only"):
            _indexed_json(repo, "id", token, "--scope", "prefix", expected=1, error="not_found")
        _indexed_json(repo, "id", "check_token", "--scope", "prefix", "--at", "HEAD",
                      expected=2, error="outside_scope")
        _indexed_json(repo, "id", "check_token", expected=3, error="not_built")
        assert path.read_bytes() == before
        assert (repo.root / "security.py").read_bytes() == dirty
        assert repo._run("show", ":security.py") == staged

    @pytest.mark.parametrize("close_target", ["session", "repository"])
    def test_query_close_failure_emits_one_empty_error_envelope(self, indexed5, monkeypatch, close_target):
        from gita.index import query
        from gita.vcs.git import CommittedRepo

        owner = query.IndexSession if close_target == "session" else CommittedRepo
        original_close = owner.close
        failed = []

        def fail_once_after_close(resource):
            original_close(resource)
            if not failed:
                failed.append(id(resource))
                raise query.QueryError("io_error", "Injected close failure after cleanup")

        monkeypatch.setattr(owner, "close", fail_once_after_close)
        payload = _indexed_json(indexed5["repo"], "id", indexed5["eid"],
                                expected=4, budget=2000, error="io_error")
        assert len(failed) == 1
        assert payload["command"] == "id"
        assert payload["status"] == "io_error"
        assert payload["results"] == []
        assert payload["page"]["shown"] == 0

