    def test_off_first_parent_since_is_rejected_before_creating_storage(self, refactor_repo):
        import subprocess
        from gita.index.store import IndexStore

        repo = refactor_repo["repo"]
        path = IndexStore.locate(repo)
        assert not path.exists() and not path.parent.exists()
        tree = repo._run("rev-parse", "HEAD^{tree}").decode("ascii").strip()
        side = subprocess.run(
            ["git", "-C", str(repo.root), "-c", "commit.gpgsign=false", "commit-tree", tree,
             "-p", refactor_repo["commits"][0], "-m", "Side boundary outside first-parent history"],
            check=True, capture_output=True,
        ).stdout.decode("ascii").strip()
        repo._run("update-ref", "refs/heads/side-boundary", side)
        assert side not in repo._run("rev-list", "--first-parent", "HEAD").decode("ascii").splitlines()
        status_before = repo._run("status", "--porcelain=v1", "--untracked-files=all")
        refs_before = repo._run("show-ref", "--head")

        payload = _indexed_json(repo, "index", "--ref", "HEAD", "--since", side,
                                expected=2, error="boundary_unavailable")

        assert payload["generation"] is None
        assert payload["results"] == []
        assert repo._run("status", "--porcelain=v1", "--untracked-files=all") == status_before
        assert repo._run("show-ref", "--head") == refs_before
        assert not path.exists()
        assert not path.parent.exists()
